// Minimal feature extractor and predictor sketch (pseudo)
function featurize(text, vocab){
  const tokens = text.toLowerCase().split(/\W+/);
  const vec = new Array(vocab.length).fill(0);
  tokens.forEach(t => { const idx = vocab.indexOf(t); if (idx>=0) vec[idx]+=1; });
  return vec;
}
function predict(vec, weights){
  let score=0; for(let i=0;i<vec.length;i++) score += vec[i]*weights[i];
  return score>0 ? 1 : 0;
}
```

